select id, balance, status, min(balance) over (partition by account_type order by balance, id rows between unbounded preceding and current row) as running_min_balance, avg(balance) over (partition by account_type order by balance, id rows between unbounded preceding and current row) as running_avg_balance, count(balance) over (partition by account_type order by balance, id rows between unbounded preceding and current row) as running_count_balance, sum(balance) over (partition by account_type order by balance, id rows between unbounded preceding and current row) as running_sum_balance from accounts;
